const KM=[{k:'nvl',n:'Nguyên vật liệu',l:'NVL trực tiếp',c:'var(--k-nvl)',h:'#EF6C00'},{k:'bb',n:'Bao bì',l:'Bao bì',c:'var(--k-bb)',h:'#FFB74D'},{k:'labor',n:'Nhân công trực tiếp',l:'Nhân công TT',c:'var(--k-nc)',h:'#0F766E'},{k:'oh',n:'Sản xuất chung',l:'SX chung',c:'var(--k-sxc)',h:'#64748B'}];
