/* ===== TRA CỨU & TÍNH TOÁN ===== */
const prod=id=>S.products.find(p=>p.id===id);
const mat=id=>S.mats.find(m=>m.id===id);
const perOf=m=>S.periods.find(p=>p.m===m);
const pers=()=>[...S.periods].sort((a,b)=>b.m.localeCompare(a.m)); // mới nhất trước
const latestM=()=>{const l=pers();return l.length?l[0].m:CURM};
const mprice=(per,m)=>per&&per.mp&&per.mp[m.id]!==undefined?+per.mp[m.id]:+m.price||0;
const groups=()=>[...new Set(S.products.map(p=>p.group).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'vi'));
const ZT=()=>({qty:0,nvl:0,bb:0,labor:0,oh:0,total:0,rev:0});
function calc(per){
  if(!per)return {rows:[],T:ZT(),ohTotal:0,base:0,rate:0,per:null};
  const rows=per.lines.map(l=>{const p=prod(l.pid);if(!p)return null;const q=+l.qty||0;let nvl=0,bb=0;const det=[];
    (p.bom||[]).forEach(b=>{const m=mat(b.mid);if(!m)return;const pr=mprice(per,m),used=q*(+b.qty||0),amt=used*pr;
      det.push({m,norm:+b.qty||0,used,price:pr,amt});if(m.kind==='BB')bb+=amt;else nvl+=amt});
    return {p,qty:q,labor:+l.labor||0,nvl,bb,det}}).filter(Boolean);
  const ohTotal=(per.oh||[]).reduce((s,o)=>s+(+o.amt||0),0);
  const w=r=>per.basis==='nvl'?r.nvl:per.basis==='labor'?r.labor:per.basis==='qty'?r.qty:r.qty*(+r.p.coef||1);
  const base=rows.reduce((s,r)=>s+w(r),0);
  rows.forEach(r=>{r.w=w(r);r.oh=base?ohTotal*r.w/base:0;r.total=r.nvl+r.bb+r.labor+r.oh;r.unit=r.qty?r.total/r.qty:0;r.rev=r.qty*(+r.p.price||0);
    r.u={nvl:r.qty?r.nvl/r.qty:0,bb:r.qty?r.bb/r.qty:0,labor:r.qty?r.labor/r.qty:0,oh:r.qty?r.oh/r.qty:0}});
  const T=ZT();rows.forEach(r=>Object.keys(T).forEach(k=>T[k]+=r[k]));
  return {rows,T,ohTotal,base,rate:base?ohTotal/base:0,per}}
const calcM=m=>calc(perOf(m));
function bomCost(p,per){let nvl=0,bb=0;(p.bom||[]).forEach(b=>{const m=mat(b.mid);if(!m)return;const v=(+b.qty||0)*(per?mprice(per,m):+m.price||0);if(m.kind==='BB')bb+=v;else nvl+=v});return {nvl,bb}}
function last12(end){const a=[];for(let i=11;i>=0;i--)a.push(mAdd(end,-i));return a}
function later(fn){setTimeout(()=>{const a=document.activeElement,k=a&&a.dataset?a.dataset.k:null;fn();
  if(k){const el=document.querySelector(`[data-k="${k}"]`);if(el){el.focus();if(el.select)el.select()}}},0)}
const marginCls=p=>p<15?'var(--danger)':p<25?'var(--warn)':'var(--ok)';
function kmLegend(){return KM.map(k=>`<span><i style="background:${k.c}"></i>${k.l}</span>`).join('')}

/* ===== DỮ LIỆU MẪU: xưởng bánh kẹo, 12 tháng ===== */
function seed(){
  let r=11;const rnd=()=>{r=(r*16807)%2147483647;return (r-1)/2147483646};const rf=(a,b)=>a+rnd()*(b-a);
  const M=[['NL01','Bột mì đa dụng','NVL','Kg',16500,.05],['NL02','Đường tinh luyện','NVL','Kg',21000,.08],['NL03','Bơ lạt','NVL','Kg',185000,.12],
    ['NL04','Trứng gà','NVL','Quả',2800,.06],['NL05','Bột cacao','NVL','Kg',210000,.1],['NL06','Sữa bột nguyên kem','NVL','Kg',120000,.03],
    ['NL07','Gạo nếp','NVL','Kg',24000,.04],['NL08','Cơm dừa nạo','NVL','Kg',45000,-.04],['NL09','Khoai tây tươi','NVL','Kg',14000,.09],
    ['NL10','Dầu ăn thực vật','NVL','Lít',42000,.05],['NL11','Muối, gia vị','NVL','Kg',30000,.02],
    ['BB01','Hộp giấy in 300g','BB','Cái',3200,.03],['BB02','Khay nhựa định hình','BB','Cái',900,.02],['BB03','Túi màng ghép in sẵn','BB','Cái',650,.02],
    ['BB04','Túi nhôm snack 60g','BB','Cái',420,.03],['BB05','Thùng carton 5 lớp','BB','Thùng',9500,.05],['BB06','Tem nhãn, hạn sử dụng','BB','Cái',150,0]];
  const mats=M.map(a=>({id:'m'+a[0],code:a[0],name:a[1],kind:a[2],unit:a[3],price:a[4],note:''}));
  const P=[['SP01','Bánh quy bơ hộp 300g','Bánh quy','Hộp',42000,1.6,[['NL01',.16],['NL02',.06],['NL03',.045],['NL04',1],['NL06',.01],['BB01',1],['BB02',1],['BB06',1],['BB05',1/24]],[8000,11000],3500],
    ['SP02','Bánh quy socola hộp 300g','Bánh quy','Hộp',46000,1.6,[['NL01',.15],['NL02',.06],['NL03',.035],['NL05',.02],['NL04',1],['NL06',.01],['BB01',1],['BB02',1],['BB06',1],['BB05',1/24]],[6000,8500],3600],
    ['SP03','Bánh bông lan cuộn 200g','Bánh mềm','Gói',28000,1,[['NL01',.07],['NL02',.05],['NL04',2],['NL03',.015],['NL06',.008],['NL10',.01],['BB03',1],['BB02',1],['BB06',1],['BB05',1/30]],[10000,14000],2500],
    ['SP04','Bánh gạo nướng 150g','Bánh gạo','Gói',16500,.8,[['NL07',.14],['NL02',.02],['NL10',.015],['NL11',.003],['BB03',1],['BB06',1],['BB05',1/30]],[15000,21000],1800],
    ['SP05','Kẹo dừa sữa túi 250g','Kẹo','Túi',27000,1,[['NL08',.12],['NL02',.1],['NL06',.02],['BB03',1],['BB06',1],['BB05',1/40]],[7000,9500],2600],
    ['SP06','Snack khoai tây 60g','Snack','Gói',9500,.35,[['NL09',.25],['NL10',.02],['NL11',.002],['BB04',1],['BB05',1/50]],[30000,42000],800]];
  const products=P.map(a=>({id:'p'+a[0],code:a[0],name:a[1],group:a[2],unit:a[3],price:a[4],coef:a[5],note:'',bom:a[6].map(([c,q])=>({mid:'m'+c,qty:Math.round(q*10000)/10000}))}));
  const periods=[];
  for(let i=0;i<12;i++){
    const m=mAdd(CURM,i-11),mo=+m.slice(5),season=mo===12||mo===1?1.35:mo===11||mo===2?1.15:1;
    const mp={};M.forEach(a=>{mp['m'+a[0]]=i===11?a[4]:Math.round(a[4]*(1-a[5]*(11-i)/11)*(1+rf(-.015,.015))/10)*10});
    const lines=P.map(a=>{const q=Math.round(rf(a[7][0],a[7][1])*season/10)*10;return {pid:'p'+a[0],qty:q,labor:Math.round(q*a[8]*rf(.96,1.07)/1000)*1000}});
    const k=x=>Math.round(x/1000)*1000;
    const oh=[{name:'Khấu hao máy móc, nhà xưởng',amt:85000000},{name:'Điện, nước, gas sản xuất',amt:k(rf(58,80)*1e6*Math.sqrt(season))},{name:'Lương quản lý phân xưởng',amt:52000000},
      {name:'Sửa chữa, bảo trì thiết bị',amt:k(rf(8,20)*1e6)},{name:'Vật tư phụ, công cụ dụng cụ',amt:k(rf(10,16)*1e6)}];
    periods.push({id:'k'+m,m,basis:'coef',mp,lines,oh,note:''})}
  return {ver:1,products,mats,periods,updated:0}}

/* ===== THANH BÊN ===== */
function chrome(){
  const m=latestM(),C=calcM(m),T=C.T;
  $('#sbLbl').textContent='Tổng giá thành '+mLbl(m).toLowerCase();
  $('#sbValue').textContent=money(T.total);
  const sh=T.total?(T.nvl+T.bb)/T.total*100:0;$('#sbBar').style.width=sh+'%';
  $('#sbNote').textContent=T.total?`NVL + bao bì chiếm ${pct(sh)} · ${C.rows.length} sản phẩm`:'Chưa có số liệu kỳ này';
  const miss=S.products.filter(p=>!(p.bom||[]).length).length,b=$('#bdBom');
  if(b){b.style.display=miss?'':'none';b.textContent=miss;b.title=miss+' sản phẩm chưa có định mức'}}

