let DSEL=null,DPROD=null;
$('#dPer').onchange=e=>{DSEL=e.target.value;renderDashboard()};
$('#dProd').onchange=e=>{DPROD=e.target.value;drawProdTrend()};
function renderDashboard(){
  const list=pers();
  if(!list.length){$('#dHero').innerHTML=`<div><div class="h-k">CHƯA CÓ KỲ TÍNH GIÁ THÀNH</div><div class="h-v" style="font-size:24px">Bắt đầu bằng danh mục và định mức</div><div class="h-act"><button class="hbtn" onclick="go('products')">Khai báo sản phẩm</button><button class="hbtn ghost" onclick="go('period')">Tạo kỳ đầu tiên</button></div></div>`;
    ['#kpis','#unitBars','#chDonut','#chTrend','#chProd','#dVar','#dMargin','#dMat','#mSum','#pSum'].forEach(s=>$(s).innerHTML='');$('#dPer').innerHTML='';$('#dCmp').textContent='';return}
  if(!DSEL||!perOf(DSEL))DSEL=list[0].m;
  $('#dPer').innerHTML=list.map(p=>`<option value="${p.m}"${p.m===DSEL?' selected':''}>${mLbl(p.m)}</option>`).join('');
  const pm=mAdd(DSEL,-1),C=calcM(DSEL),P=perOf(pm)?calcM(pm):null,T=C.T,PT=P?P.T:null;
  $('#dCmp').textContent=P?'So sánh với '+mLbl(pm).toLowerCase():'Chưa có số liệu tháng trước để so sánh';
  const months=last12(DSEL),ser=months.map(m=>calcM(m).T),labels=months.map(mTick);
  const gp=T.rev-T.total,mg=T.rev?gp/T.rev*100:0;
  $('#dHero').innerHTML=`<div>
      <div class="h-k">TỔNG GIÁ THÀNH ${mLbl(DSEL).toUpperCase()}</div>
      <div class="h-v"><span data-count="${Math.round(T.total)}">0</span> <small>₫</small></div>
      <div class="h-sub">${pill(T.total,PT?PT.total:undefined,'so với tháng trước',true)}<span>${PT?'tháng trước '+short(PT.total)+' ₫':'chưa có tháng trước'}</span></div>
      <div class="h-stats"><div><b data-count="${T.qty}">0</b><span>Sản phẩm hoàn thành</span></div><div><b data-count="${C.rows.length}">0</b><span>Mã sản phẩm</span></div><div><b>${short(C.ohTotal)}</b><span>Chi phí SX chung</span></div></div>
      <div class="h-act"><button class="hbtn" onclick="PSEL='${DSEL}';go('period')">Nhập chi phí kỳ này</button><button class="hbtn ghost" onclick="RSEL='${DSEL}';go('report')">Bảng tính giá thành</button></div>
    </div>
    <div class="h-chart"><div class="h-ct"><span>Tổng giá thành 12 tháng</span><span>Bình quân <b>${short(ser.reduce((s,t)=>s+t.total,0)/Math.max(1,ser.filter(t=>t.total).length))} ₫</b></span></div>${heroArea(labels,ser.map(t=>t.total))}</div>
    <div class="h-ring">${ring(mg,'biên lãi gộp')}<b>Lãi gộp ${short(gp)} ₫</b><span>doanh thu theo giá bán ${short(T.rev)} ₫</span></div>`;
  const icons={nvl:IC.box,bb:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16l-1.5 13a1 1 0 01-1 .9H6.5a1 1 0 01-1-.9z"/><path d="M8 7V5a4 4 0 018 0v2"/></svg>',labor:IC.user,oh:IC.gear};
  const bgs={nvl:'#fff1e6',bb:'#fff6e8',labor:'#e3f4f1',oh:'#eef1f6'};
  $('#kpis').innerHTML=KM.map(k=>kc({c:k.h,cb:bgs[k.k],icon:icons[k.k],label:k.n,value:T[k.k],unit:'₫',pill:pill(T[k.k],PT?PT[k.k]:undefined,'so với tháng trước',true),
    sub:`Chiếm <b>${pct(T.total?T[k.k]/T.total*100:0)}</b> giá thành${k.k==='oh'?' · phân bổ theo '+(BASIS[C.per.basis]||'').split(' (')[0].toLowerCase():''}`,data:ser.map(t=>t[k.k])})).join('');
  $('#kmLeg1').innerHTML=kmLegend();$('#kmLeg2').innerHTML=kmLegend();
  // giá thành đơn vị từng sản phẩm
  const prevU={};if(P)P.rows.forEach(r=>prevU[r.p.id]=r);
  const rows=[...C.rows].sort((a,b)=>b.unit-a.unit),mx=Math.max(1,...rows.map(r=>Math.max(r.unit,+r.p.price||0)))*1.04;
  $('#unitBars').innerHTML=rows.length?rows.map(r=>{const pv=prevU[r.p.id],d=pv&&pv.unit?(r.unit-pv.unit)/pv.unit*100:null;
    return `<div class="ub"><div class="ub-h"><b>${esc(r.p.name)}</b><small>${esc(r.p.code)} · ${fmt(r.qty)} ${esc(r.p.unit)}</small><span class="v">${fmt(r.unit)} ₫${d===null?'':`<em class="${d>0?'up':'dn'}">${d>0?'▲':'▼'} ${fmtD(Math.abs(d),1)}%</em>`}</span></div>
    <div class="ub-t"><div class="stk">${KM.map(k=>`<i style="width:${r.u[k.k]/mx*100}%;background:${k.c}" data-tip="${esc(k.n+': '+fmt(r.u[k.k])+' ₫/'+r.p.unit+' ('+pct(r.unit?r.u[k.k]/r.unit*100:0)+')')}"></i>`).join('')}</div>${r.p.price?`<span class="pr" style="left:${r.p.price/mx*100}%" data-l="${short(r.p.price)}" data-tip="${esc('Giá bán '+fmt(r.p.price)+' ₫')}"></span>`:''}</div></div>`}).join(''):'<div class="empty">Kỳ này chưa có sản phẩm nào</div>';
  $('#donHint').textContent=mLbl(DSEL);
  $('#chDonut').innerHTML=donut(KM.map(k=>({label:k.n,value:T[k.k],color:k.h})),'Tổng giá thành');
  const sm=ser.reduce((s,t)=>s+t.total,0),act=ser.filter(t=>t.total),hi=ser.reduce((b,t,i)=>t.total>ser[b].total?i:b,0);
  $('#mSum').innerHTML=`<div><small>Tổng 12 tháng</small><b>${short(sm)} ₫</b></div><div><small>Bình quân tháng</small><b>${short(sm/Math.max(1,act.length))} ₫</b></div><div><small>Cao nhất</small><b style="color:var(--chu-dao-dam)">${labels[hi].replace(/\/\d+$/,'')} · ${short(ser[hi].total)} ₫</b></div>`;
  $('#chTrend').innerHTML=comboChart({labels,bars:KM.map(k=>({name:k.n,color:k.h,data:ser.map(t=>t[k.k])})),stack:true,hl:11});
  // chọn sản phẩm cho biểu đồ đơn vị
  if(!DPROD||!prod(DPROD))DPROD=(rows[0]||{p:S.products[0]||{}}).p.id;
  $('#dProd').innerHTML=S.products.map(p=>`<option value="${p.id}"${p.id===DPROD?' selected':''}>${esc(p.name)}</option>`).join('');
  drawProdTrend();
  // biến động
  const vars=C.rows.filter(r=>prevU[r.p.id]&&prevU[r.p.id].unit).map(r=>{const pv=prevU[r.p.id],d=r.unit-pv.unit;
    const drv=KM.map(k=>({k,v:r.u[k.k]-pv.u[k.k]})).sort((a,b)=>Math.abs(b.v)-Math.abs(a.v))[0];return {r,pv,d,p:d/pv.unit*100,drv}}).sort((a,b)=>Math.abs(b.p)-Math.abs(a.p)).slice(0,6);
  $('#dVar').innerHTML=vars.length?vars.map(o=>`<div class="li"><span class="tico" style="background:${o.d>0?'var(--dangerbg)':'var(--okbg)'};color:${o.d>0?'var(--danger)':'var(--ok)'}">${o.d>0?IC.up:IC.up.replace('<svg','<svg style="transform:scaleY(-1)"')}</span><div class="meta"><b>${esc(o.r.p.name)}</b><small>${fmt(o.pv.unit)} → ${fmt(o.r.unit)} ₫ · chủ yếu do ${o.drv.k.n.toLowerCase()} (${o.drv.v>0?'+':''}${fmt(o.drv.v)} ₫)</small></div><div class="v ${o.d>0?'up':'dn'}">${o.d>0?'+':''}${fmtD(o.p,1)}%<small>${o.d>0?'+':''}${fmt(o.d)} ₫</small></div></div>`).join(''):'<div class="empty">Chưa có tháng trước để so sánh</div>';
  // biên lãi
  const mrows=C.rows.filter(r=>r.p.price).map(r=>({r,m:(r.p.price-r.unit)/r.p.price*100})).sort((a,b)=>a.m-b.m);
  $('#dMargin').innerHTML=mrows.length?mrows.map(o=>`<div class="li"><div class="meta"><b>${esc(o.r.p.name)}</b><small>Giá bán ${fmt(o.r.p.price)} · giá thành ${fmt(o.r.unit)}</small><div class="pbar"><i style="width:${Math.max(2,Math.min(100,o.m))}%;background:${marginCls(o.m)}"></i></div></div><div class="v" style="color:${marginCls(o.m)}">${pct(o.m)}<small>${fmt(o.r.p.price-o.r.unit)} ₫/${esc(o.r.p.unit)}</small></div></div>`).join(''):'<div class="empty">Chưa khai báo giá bán sản phẩm</div>';
  // NVL lớn nhất
  const agg={};C.rows.forEach(r=>r.det.forEach(d=>{const a=agg[d.m.id]=agg[d.m.id]||{m:d.m,amt:0,used:0,price:d.price};a.amt+=d.amt;a.used+=d.used}));
  const mm=Object.values(agg).sort((a,b)=>b.amt-a.amt).slice(0,6),base=T.nvl+T.bb||1,pp=perOf(pm);
  $('#dMat').innerHTML=mm.length?mm.map((a,i)=>{const op=pp?mprice(pp,a.m):null,ch=op?(a.price-op)/op*100:null;
    return `<div class="li"><span class="medal" style="background:${i<3?['#EF6C00','#FB8C00','#FFB74D'][i]:'#c3cbda'}">${i+1}</span><div class="meta"><b>${esc(a.m.name)}</b><small>${fmtD(a.used,1)} ${esc(a.m.unit)} · ${pct(a.amt/base*100)} chi phí NVL, bao bì${ch===null?'':` · giá <span class="${ch>0.05?'up':ch<-0.05?'dn':''}">${ch>0?'▲':ch<0?'▼':''} ${fmtD(Math.abs(ch),1)}%</span>`}</small></div><div class="v">${short(a.amt)}</div></div>`}).join(''):'<div class="empty">Chưa có định mức</div>';
  countUp($('#page-dashboard'))}
function drawProdTrend(){
  const months=last12(DSEL||latestM()),p=prod(DPROD);if(!p){$('#chProd').innerHTML='<div class="empty">Chưa có sản phẩm</div>';$('#pSum').innerHTML='';return}
  const u=months.map(m=>{const r=calcM(m).rows.find(x=>x.p.id===p.id);return r&&r.qty?Math.round(r.unit):null});
  const have=u.filter(v=>v!==null);
  $('#pSum').innerHTML=have.length?`<div><small>Kỳ đang xem</small><b style="color:var(--chu-dao-dam)">${u[11]===null?'-':fmt(u[11])+' ₫'}</b></div><div><small>Thấp nhất 12 tháng</small><b>${fmt(Math.min(...have))} ₫</b></div><div><small>Cao nhất 12 tháng</small><b>${fmt(Math.max(...have))} ₫</b></div><div><small>Giá bán</small><b>${fmt(p.price)} ₫</b></div>`:'';
  $('#chProd').innerHTML=have.length?comboChart({labels:months.map(mTick),lines:[{name:'Giá thành đơn vị',color:'#EF6C00',data:u},...(p.price?[{name:'Giá bán',color:'#1d2330',dash:true,data:months.map(()=>p.price)}]:[])],hl:11,yFmt:v=>short(v),H:260}):'<div class="empty">Sản phẩm này chưa có số liệu 12 tháng qua</div>'}

