let TMODE='unit';
$$('#tMode button').forEach(b=>b.onclick=()=>{TMODE=b.dataset.v;$$('#tMode button').forEach(x=>x.classList.toggle('on',x===b));renderTrend()});
$('#tKm').onchange=()=>renderTrend();
function trendData(){const months=last12(latestM()),km=$('#tKm').value,cs=months.map(calcM);
  const val=(r)=>{if(!r)return null;if(TMODE==='qty')return r.qty;const v=km?r[km]:r.total;return TMODE==='unit'?(r.qty?v/r.qty:null):v};
  const rows=S.products.map(p=>({p,v:cs.map(C=>val(C.rows.find(x=>x.p.id===p.id)))})).filter(o=>o.v.some(x=>x!==null)).sort((a,b)=>a.p.code.localeCompare(b.p.code));
  return {months,rows,cs,km}}
function renderTrend(){
  const {months,rows,cs,km}=trendData(),kmn=km?KM.find(k=>k.k===km).n.toLowerCase():'';
  const ttl=TMODE==='qty'?'Sản lượng hoàn thành':TMODE==='unit'?'Giá thành đơn vị'+(km?' (phần '+kmn+')':''):'Tổng giá thành'+(km?' (phần '+kmn+')':'');
  $('#tTitle').textContent=ttl+' 12 tháng, '+mLbl(months[0]).toLowerCase()+' đến '+mLbl(months[11]).toLowerCase();
  $('#tPrintLbl').textContent=ttl+' · '+mLbl(months[0])+' - '+mLbl(months[11]);
  const inv=TMODE!=='qty';
  $('#tTable').innerHTML=rows.length?`<table><thead><tr><th>Sản phẩm</th>${months.map((m,i)=>`<th class="n">${mTick(m,i)}</th>`).join('')}<th class="n">Bình quân</th><th class="n">Đầu kỳ → cuối kỳ</th></tr></thead><tbody>
    ${rows.map(o=>{const have=o.v.filter(x=>x!==null),avg=have.reduce((s,x)=>s+x,0)/Math.max(1,have.length),f=o.v.find(x=>x!==null),l=[...o.v].reverse().find(x=>x!==null),ch=f?(l-f)/f*100:0;
      return `<tr><td><div class="pcell"><b>${esc(o.p.name)}</b><small>${esc(o.p.code)} · ${esc(o.p.unit)}</small></div></td>${o.v.map((v,i)=>{const pv=i?o.v[i-1]:null,d=v!==null&&pv?(v-pv)/pv*100:0;
        return `<td class="n ${d>3?(inv?'heat-up':'heat-dn'):d<-3?(inv?'heat-dn':'heat-up'):''}" ${v!==null&&pv?`data-tip="${esc(mLbl(months[i])+': '+(d>=0?'+':'')+fmtD(d,1)+'% so tháng trước')}"`:''}>${v===null?'-':fmt(v)}</td>`}).join('')}
        <td class="n"><b>${fmt(avg)}</b></td><td class="n ${ch>0?(inv?'up':'dn'):ch<0?(inv?'dn':'up'):''}"><b>${ch>0?'+':''}${fmtD(ch,1)}%</b></td></tr>`}).join('')}</tbody>
    ${TMODE!=='unit'?`<tfoot><tr><td>Cộng</td>${months.map((m,i)=>`<td class="n">${fmt(rows.reduce((s,o)=>s+(o.v[i]||0),0))}</td>`).join('')}<td></td><td></td></tr></tfoot>`:''}</table>`:'<div class="empty">Chưa có số liệu</div>'}

