function perRows(m){const C=calcM(m);return C.rows.map(r=>[mLbl(m),r.p.code,r.p.name,r.p.unit,r.qty,r.nvl,r.bb,r.labor,r.oh,r.total,Math.round(r.unit),r.p.price,r.p.price?Math.round(r.p.price-r.unit):'',r.p.price?(r.p.price-r.unit)/r.p.price*100:''])}
const PER_COLS=[{label:'Kỳ',width:14},{label:'Mã SP',width:9},{label:'Tên sản phẩm',width:30},{label:'ĐVT',width:7},{label:'Sản lượng',type:'int',sum:true,width:11},{label:'NVL trực tiếp',type:'money',sum:true},{label:'Bao bì',type:'money',sum:true},{label:'Nhân công trực tiếp',type:'money',sum:true},{label:'SX chung phân bổ',type:'money',sum:true},{label:'Tổng giá thành',type:'money',sum:true,width:16},{label:'Giá thành đơn vị',type:'money'},{label:'Giá bán',type:'money',width:12},{label:'Lãi gộp / ĐV',type:'money',width:12},{label:'Biên lãi gộp',type:'pct'}];
