function renderGuide(){$('#page-guide').innerHTML=`<div class="guide">
  <div class="card"><h3>File này dùng để làm gì?</h3>
    <p>Tính giá thành từng sản phẩm theo tháng cho xưởng, công ty sản xuất. Giá thành gồm 4 khoản: <b>nguyên vật liệu</b> và <b>bao bì</b> (định mức x đơn giá), <b>nhân công trực tiếp</b> và <b>chi phí sản xuất chung</b> (tự phân bổ theo tiêu thức chọn). Dashboard cho thấy cơ cấu giá thành, giá thành đơn vị từng sản phẩm, xu hướng theo tháng và biên lãi so với giá bán.</p>
    <h3 style="margin-top:14px">Các bước dùng</h3>
    <ol class="steps">
      <li><b>Xóa dữ liệu mẫu</b><span>Vào Cài đặt &amp; dữ liệu, bấm "Xóa dữ liệu" để bắt đầu với số liệu thật. Muốn xem lại mẫu thì bấm "Nạp dữ liệu mẫu".</span></li>
      <li><b>Khai báo danh mục</b><span>Mục NVL &amp; bao bì: nhập tên, đơn vị tính, đơn giá. Mục Sản phẩm: nhập tên, giá bán, hệ số quy đổi. Có thể nhập cả danh sách từ file Excel.</span></li>
      <li><b>Lập định mức</b><span>Mục Định mức: với mỗi sản phẩm, chọn từng NVL, bao bì và lượng dùng cho 1 đơn vị sản phẩm.</span></li>
      <li><b>Nhập chi phí từng tháng</b><span>Mục Chi phí theo kỳ: tạo kỳ mới, nhập sản lượng hoàn thành, chi phí lương công nhân trực tiếp, các khoản chi phí chung và chọn tiêu thức phân bổ. Sửa đơn giá NVL nếu tháng đó giá khác.</span></li>
      <li><b>Xem kết quả</b><span>Dashboard, Bảng tính giá thành (in được, có thẻ tính giá thành từng sản phẩm) và Giá thành qua các tháng để so sánh.</span></li>
      <li><b>Lưu và xuất</b><span>Bấm "Lưu đè dữ liệu" để ghi vào chính file này. Bấm "Xuất Excel" để tải file .xlsx gồm mọi bảng.</span></li>
    </ol></div>
  <div>
    <div class="card"><h3>Lưu đè dữ liệu</h3>
      <p>Dữ liệu nằm ngay trong file .html. Bấm <b>Lưu đè dữ liệu</b> (hoặc <span class="kbd">Ctrl</span> + <span class="kbd">S</span>):</p>
      <p>• Chrome, Edge trên máy tính: lần đầu chọn đúng file đang mở để ghi đè, các lần sau lưu thẳng.<br>• Điện thoại, Firefox: trình duyệt tải về bản mới cùng tên, hãy dùng file vừa tải.</p>
      <p>Mỗi lần sửa, file còn tự giữ bản tạm trong trình duyệt. Lỡ đóng mà chưa lưu, mở lại sẽ được hỏi có khôi phục không.</p></div>
    <div class="card" style="margin-top:16px"><h3>Cách tính trong file</h3>
      <p>• NVL, bao bì = sản lượng x định mức x đơn giá của kỳ.<br>• Chi phí chung của sản phẩm = tổng chi phí chung x tiêu thức của sản phẩm / tổng tiêu thức.<br>• Giá thành đơn vị = tổng giá thành / sản lượng hoàn thành.</p>
      <div class="note">File tính theo phương pháp giản đơn, chưa tính sản phẩm dở dang đầu kỳ, cuối kỳ. Đây là file mẫu, cần điều chỉnh cho đúng quy trình đơn vị mình.</div>
      <div class="gift">File mẫu tặng học viên lớp Excel cuối tuần - thầy Phong Excel</div></div>
  </div></div>`}

/* =========================================================
   DỮ LIỆU
   - Nguồn chính: khối <script id="du-lieu"> nằm ngay trong file (nút "Lưu đè dữ liệu" ghi vào)
   - Bản tạm: bộ nhớ trình duyệt (localStorage), giữ thay đổi chưa kịp lưu vào file
   ========================================================= */
const ONLINE=/^https?:$/.test(location.protocol);
const FILE_NAME=ONLINE?APP.file:decodeURIComponent(location.pathname.split('/').pop()||APP.file);
const LS=APP.ls+'|'+location.pathname;
const EMB=(()=>{try{return JSON.parse($('#du-lieu').textContent)}catch(e){return null}})();
let DIRTY=false,DRAFT_ASK=null;
let S=APP.valid(EMB)?EMB:APP.seed();
(()=>{let d=null;try{d=JSON.parse(localStorage.getItem(LS))}catch(e){}
  if(APP.valid(d)&&(d.updated||0)>((APP.valid(EMB)&&EMB.updated)||0))DRAFT_ASK=d})();
let SAVED_AT=APP.valid(EMB)?(EMB.savedAt||0):0;
function persist(d){try{localStorage.setItem(LS,JSON.stringify(d));return true}catch(e){return false}}
function save(){S.updated=Date.now();DIRTY=true;
  if(!persist(S))toast('Bộ nhớ tạm của trình duyệt đã đầy, hãy bấm "Lưu đè dữ liệu" để ghi vào file ngay','err');
  refreshChrome();refreshSave()}

/* =========================================================
   LƯU ĐÈ VÀO CHÍNH FILE HTML
   ========================================================= */
let FH=null;
const idb=(mode,fn)=>new Promise((ok,no)=>{const rq=indexedDB.open('file_mau_luu_de',1);rq.onupgradeneeded=()=>rq.result.createObjectStore('h');
  rq.onsuccess=()=>{const tx=rq.result.transaction('h',mode),r=fn(tx.objectStore('h'));tx.oncomplete=()=>ok(r&&r.result);tx.onerror=()=>no(tx.error)};rq.onerror=()=>no(rq.error)});
const idbGet=k=>idb('readonly',s=>s.get(k)).catch(()=>null);
const idbSet=(k,v)=>idb('readwrite',s=>s.put(v,k)).catch(()=>null);
function buildHtml(data){
  const json=JSON.stringify(data).replace(/</g,'\\u003c');
  const open='<script id="du-lieu" type="application/json">',close='</scr'+'ipt>';
  const a=TEMPLATE.indexOf(open),b=TEMPLATE.indexOf(close,a);
  return '<!DOCTYPE html>\n'+TEMPLATE.slice(0,a+open.length)+json+TEMPLATE.slice(b)}
async function saveToFile(){
  const data={...S,savedAt:Date.now()};data.updated=Math.max(S.updated||0,data.savedAt);
  const html=buildHtml(data);
  if(ONLINE||!window.showSaveFilePicker)return downloadHtml(html,data);
  try{
    let h=FH;
    if(!h){const kept=await idbGet(LS);if(kept&&kept.name===FILE_NAME)h=kept}
    if(h){let p=await h.queryPermission({mode:'readwrite'});if(p!=='granted')p=await h.requestPermission({mode:'readwrite'});if(p!=='granted')h=null}
    if(!h){if(!await askPick())return;
      h=await showSaveFilePicker({suggestedName:FILE_NAME,types:[{description:'Trang HTML',accept:{'text/html':['.html']}}]})}
    const w=await h.createWritable();await w.write(html);await w.close();
    FH=h;idbSet(LS,h);done(data);
    toast(h.name===FILE_NAME?'Đã lưu đè dữ liệu vào file '+h.name:'Đã lưu vào file '+h.name+' (khác tên file đang mở)');
  }catch(e){if(e&&e.name==='AbortError')return;console.error(e);downloadHtml(html,data)}}
function done(data){S.updated=data.updated;S.savedAt=data.savedAt;SAVED_AT=data.savedAt;DIRTY=false;persist(S);refreshSave()}
function downloadHtml(html,data){
  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([html],{type:'text/html'}));a.download=FILE_NAME;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},2000);
  done(data);toast('Trình duyệt này không cho ghi đè trực tiếp, đã tải bản mới về máy (thư mục Tải xuống). Hãy dùng file vừa tải từ giờ.','err')}
function askPick(){return new Promise(res=>{
  openModal(MH('Lưu lần đầu vào file')+`<div class="modal-b"><p>Trình duyệt cần chỉ đúng file để ghi đè <b>một lần duy nhất</b>:</p>
  <ol><li>Bấm <b>Chọn file để ghi đè</b> bên dưới.</li><li>Tìm tới thư mục chứa file đang mở, chọn đúng file <b>${esc(FILE_NAME)}</b>.</li><li>Bấm <b>Save / Lưu</b>, rồi bấm <b>Yes / Có</b> khi được hỏi có thay file cũ không.</li><li>Nếu trình duyệt hỏi quyền chỉnh sửa, bấm <b>Allow / Cho phép</b>.</li></ol>
  <p class="muted">Từ lần sau chỉ cần bấm "Lưu đè dữ liệu" hoặc <span class="kbd">Ctrl</span> + <span class="kbd">S</span> là xong.</p></div>
  <div class="modal-f"><button class="btn" id="pkNo">Để sau</button><button class="btn pri" id="pkYes">Chọn file để ghi đè</button></div>`,'small');
  $('#pkNo').onclick=()=>{closeModal();res(false)};$('#pkYes').onclick=()=>{closeModal();res(true)}})}
async function forgetFile(){FH=null;await idbSet(LS,null);saveToFile()}
function refreshSave(){
  const st=$('#saveSt'),bt=$('#saveBtn');
  bt.classList.toggle('dirty',DIRTY);st.className='savest '+(DIRTY?'dirty':'clean');
  st.innerHTML=DIRTY?'<b>Chưa lưu vào file</b>có thay đổi mới':SAVED_AT?'<b>Đã lưu vào file</b>lúc '+hm(SAVED_AT):'<b>Dữ liệu mẫu</b>chưa lưu lần nào'}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveToFile()}
  if(e.key==='Escape')closeModal()});
window.addEventListener('beforeunload',e=>{if(DIRTY){e.preventDefault();e.returnValue=''}});
$('#ov').addEventListener('mousedown',e=>{if(e.target.id==='ov')closeModal()});

/* =========================================================
   ĐIỀU HƯỚNG
   ========================================================= */
let CUR='dashboard';
function go(pg){
  if(!APP.pages[pg])pg='dashboard';CUR=pg;
  $$('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===pg));
  $$('.page').forEach(s=>s.classList.toggle('show',s.id==='page-'+pg));
  $('#pTitle').textContent=APP.pages[pg][0];$('#pSub').textContent=APP.pages[pg][1];
  APP.pages[pg][2]();
  try{if(location.hash!=='#'+pg)history.replaceState(null,'','#'+pg)}catch(e){}
  $('#sb').classList.remove('open');$('#mask').classList.remove('show');window.scrollTo(0,0)}
$$('#nav a').forEach(a=>a.onclick=()=>go(a.dataset.page));
$('#burger').onclick=()=>{$('#sb').classList.add('open');$('#mask').classList.add('show')};
$('#mask').onclick=()=>{$('#sb').classList.remove('open');$('#mask').classList.remove('show')};
function rerender(){APP.pages[CUR][2]()}
function refreshChrome(){APP.chrome()}

/* =========================================================
   CÀI ĐẶT & DỮ LIỆU (dùng chung)
   ========================================================= */
function renderSettings(){
  const co=S.company||{};
  $('#page-settings').innerHTML=`<div class="set-grid">
    <div class="card"><div class="set-ic" style="background:#eceef3;color:var(--sb)">${IC.check}</div><h4>Lưu đè vào file</h4><p>Ghi toàn bộ dữ liệu hiện tại vào chính file .html này. Lần sau mở file là thấy dữ liệu mới nhất. Phím tắt: Ctrl + S.</p><button class="btn save" onclick="saveToFile()">Lưu đè dữ liệu</button> <button class="btn sm" onclick="forgetFile()" title="Chọn lại file để ghi đè">Chọn lại file</button></div>
    <div class="card"><div class="set-ic" style="background:var(--chu-dao-nhat);color:var(--chu-dao-dam)">${IC.xl}</div><h4>Xuất toàn bộ ra Excel</h4><p>Tải một file .xlsx, mỗi bảng dữ liệu là một sheet, mở thẳng bằng Excel để tính tiếp hoặc gửi đi.</p><button class="btn pri" onclick="APP.exportAll()">Xuất Excel</button></div>
    <div class="card"><div class="set-ic" style="background:#e6f0ff;color:#2a5bd7">${IC.dl}</div><h4>Sao lưu dữ liệu</h4><p>Tải toàn bộ dữ liệu về một file .json để cất giữ riêng, phòng khi mất file.</p><button class="btn" onclick="backup()">Tải file sao lưu</button></div>
    <div class="card"><div class="set-ic" style="background:var(--okbg);color:var(--ok)">${IC.up}</div><h4>Khôi phục dữ liệu</h4><p>Chọn file .json đã sao lưu trước đó. Dữ liệu hiện tại sẽ được thay bằng dữ liệu trong file.</p><button class="btn" onclick="$('#restoreFile').click()">Chọn file sao lưu</button><input type="file" id="restoreFile" accept=".json" hidden></div>
    <div class="card"><div class="set-ic" style="background:var(--warnbg);color:#a86b00">${IC.cal}</div><h4>Nạp lại dữ liệu mẫu</h4><p>${APP.sampleDesc}</p><button class="btn" onclick="resetSample()">Nạp dữ liệu mẫu</button></div>
    <div class="card"><div class="set-ic" style="background:var(--dangerbg);color:var(--danger)">${IC.del}</div><h4>Xóa dữ liệu mẫu để dùng thật</h4><p>${APP.clearDesc}</p><button class="btn danger" onclick="clearAll()">Xóa dữ liệu</button></div>
  </div>
  <div class="card" style="margin-top:16px;padding:20px">
    <h4 style="font-size:15px;margin-bottom:4px">Thông tin đơn vị (in trên báo cáo, phiếu)</h4>
    <p class="muted" style="font-size:13px;margin-bottom:14px">Điền một lần, các bản in sẽ tự có tên đơn vị, địa chỉ.</p>
    <div class="row2"><div class="fg"><label class="f">Tên đơn vị</label><input class="inp" id="coName" value="${esc(co.name||'')}" placeholder="${esc(APP.coHint||'VD: Công ty TNHH Minh An')}"></div><div class="fg"><label class="f">Điện thoại</label><input class="inp" id="coPhone" value="${esc(co.phone||'')}"></div></div>
    <div class="row2"><div class="fg"><label class="f">Địa chỉ</label><input class="inp" id="coAddr" value="${esc(co.addr||'')}"></div><div class="fg"><label class="f">${esc(APP.coExtra||'Bộ phận')}</label><input class="inp" id="coExtra" value="${esc(co.extra||'')}"></div></div>
    <button class="btn pri" onclick="saveCompany()">Lưu thông tin</button>
  </div>
  <div class="card" style="margin-top:16px;padding:18px" id="storeInfo"></div>`;
  $('#restoreFile').onchange=e=>{const f=e.target.files[0];if(!f)return;const fr=new FileReader();fr.onload=()=>{try{const d=JSON.parse(fr.result);if(!APP.valid(d))throw 0;
    if(!confirm('Khôi phục dữ liệu từ file sao lưu? Dữ liệu hiện tại sẽ được thay thế.'))return;S=d;save();toast('Khôi phục xong, nhớ bấm "Lưu đè dữ liệu" để ghi vào file');rerender()}catch(_){toast('File sao lưu không hợp lệ','err')}};fr.readAsText(f);e.target.value=''};
  const size=JSON.stringify(S).length;
  $('#storeInfo').innerHTML=`<b>Dung lượng dữ liệu:</b> ${fmtD(size/1024,0)} KB
  <div class="pbar" style="height:8px;margin:10px 0"><i style="width:${Math.min(100,size/5/1024/1024*100)}%;background:var(--chu-dao)"></i></div>
  <span class="muted">${APP.info()} Dữ liệu nằm ngay trong file <b>${esc(FILE_NAME)}</b> sau mỗi lần bấm "Lưu đè dữ liệu". ${DIRTY?'<b style="color:#c26a00">Hiện có thay đổi chưa lưu vào file.</b>':''}</span>`}
function saveCompany(){S.company={name:$('#coName').value.trim(),phone:$('#coPhone').value.trim(),addr:$('#coAddr').value.trim(),extra:$('#coExtra').value.trim()};save();toast('Đã lưu thông tin đơn vị')}
function backup(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(S)],{type:'application/json'}));a.download=`Sao luu ${APP.file.replace(/\.html$/,'')} ${TODAYS}.json`;a.click();toast('Đã tải file sao lưu')}
function resetSample(){if(!confirm('Thay toàn bộ dữ liệu hiện tại bằng dữ liệu mẫu?'))return;const co=S.company;S=APP.seed();if(co)S.company=co;save();toast('Đã nạp dữ liệu mẫu');rerender()}
function clearAll(){if(!confirm('Xóa dữ liệu mẫu để bắt đầu nhập dữ liệu thật? Nên tải file sao lưu trước khi xóa.'))return;const co=S.company;S=APP.empty();if(co)S.company=co;save();toast('Đã xóa dữ liệu, bắt đầu nhập dữ liệu thật');rerender()}
function companyHead(){const co=S.company||{},dots='..............................................';
  return `<div class="hd"><div><b>Đơn vị: ${esc(co.name||dots)}</b><br>Địa chỉ: ${esc(co.addr||dots)}${co.phone?'<br>Điện thoại: '+esc(co.phone):''}</div><div class="r">${co.extra?'<b>'+esc(co.extra)+'</b><br>':''}Ngày in: ${vnDate(TODAYS)}</div></div>`}

